script:
(function () {
  'use strict';
  // Rental property cash flow and returns, modelled year by year (all figures before income tax):
  //   gross income_y = (rent + other income) x 12 x (1 + rent growth)^(y-1)
  //   rent collected = gross x (1 - vacancy); management fee = rent collected x fee %
  //   operating expenses_y = (tax + insurance + maintenance + other + HOA x 12) x (1 + cost growth)^(y-1) + management
  //   NOI = rent collected - operating expenses; cash flow = NOI - mortgage payments (P&I)
  //   mortgage payment = L x i / (1 - (1 + i)^-n), i = rate / 12 (L / n at 0%)
  //   cap rate = year-1 NOI / property value; cash-on-cash = year-1 cash flow / cash invested
  //   cash invested = down payment + closing costs + repairs
  //   sale = value x (1 + appreciation)^years; cash from sale = sale x (1 - selling costs) - loan balance
  //   IRR solves NPV = 0 for [-cash invested, CF1, ..., CFn + cash from sale].
  // Verified: $240,000 at 6.5% for 30 years = $1,516.96/month (standard amortization table value);
  // balance after 10 years = $203,462.70 (closed form L(1+i)^k - P((1+i)^k - 1)/i); a simple
  // case (price $100,000 cash, $1,000/month rent, no costs/growth, sold after 1 year at cost)
  // gives NOI $12,000, cap rate 12%, cash-on-cash 12% and IRR 12%.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money2 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  // --- calc start
  function payment(loan, annualRate, years) {
    var n = years * 12, i = annualRate / 12;
    if (loan <= 0) return 0;
    return i === 0 ? loan / n : loan * i / (1 - Math.pow(1 + i, -n));
  }

  function npv(rate, flows) {
    var total = 0, factor = 1;
    for (var t = 0; t < flows.length; t++) {
      if (t > 0) factor *= 1 + rate;
      total += flows[t] / factor;
    }
    return total;
  }

  // All IRRs between -99% and 1,000% (scan for sign changes, then bisect); the one nearest 10% is used.
  function irr(flows) {
    var hasPos = flows.some(function (f) { return f > 0; }), hasNeg = flows.some(function (f) { return f < 0; });
    if (!hasPos || !hasNeg) return NaN;
    var grid = [], r, roots = [];
    for (r = -0.99; r < 1; r += 0.01) grid.push(r);
    for (r = 1; r <= 10.0001; r += 0.05) grid.push(r);
    var prevR = grid[0], prevV = npv(prevR, flows);
    for (var g = 1; g < grid.length; g++) {
      var curR = grid[g], curV = npv(curR, flows);
      if (isFinite(curV) && isFinite(prevV) && (prevV < 0) !== (curV < 0)) {
        var lo = prevR, hi = curR, loV = prevV;
        for (var k = 0; k < 200 && hi - lo > 1e-12; k++) {
          var mid = (lo + hi) / 2, midV = npv(mid, flows);
          if ((midV < 0) === (loV < 0)) { lo = mid; loV = midV; } else { hi = mid; }
        }
        roots.push((lo + hi) / 2);
      }
      prevR = curR; prevV = curV;
    }
    if (!roots.length) return NaN;
    return roots.reduce(function (a, b) { return Math.abs(b - 0.1) < Math.abs(a - 0.1) ? b : a; });
  }

  function analyze(p) {
    var down = p.price * p.downPct;
    var loan = p.price - down;
    var cashIn = down + p.closing + p.repairs;
    var value0 = p.arv > 0 ? p.arv : p.price;
    var pmt = payment(loan, p.rate, p.term);
    var i = p.rate / 12, bal = loan, month = 0;
    var fixedCosts = p.tax + p.insurance + p.maintenance + p.otherCost + p.hoa * 12;
    var rows = [], flows = [-cashIn];
    for (var y = 1; y <= p.hold; y++) {
      var gross = (p.rent + p.otherIncome) * 12 * Math.pow(1 + p.rentGrowth, y - 1);
      var collected = gross * (1 - p.vacancy);
      var opex = fixedCosts * Math.pow(1 + p.costGrowth, y - 1) + collected * p.management;
      var noi = collected - opex;
      var debt = 0;
      for (var m = 0; m < 12; m++) {
        if (bal <= 1e-9 || month >= p.term * 12) break;
        var interest = bal * i;
        var pay = Math.min(pmt, bal + interest);
        bal = bal + interest - pay;
        debt += pay;
        month++;
      }
      if (bal < 1e-6) bal = 0;
      var value = value0 * Math.pow(1 + p.appreciation, y);
      var cf = noi - debt;
      rows.push({ year: y, collected: collected, opex: opex, noi: noi, debt: debt, cashFlow: cf, value: value, balance: bal });
      flows.push(cf);
    }
    var last = rows[rows.length - 1];
    var salePrice = last.value;
    var proceeds = salePrice * (1 - p.sellCost) - last.balance;
    flows[flows.length - 1] += proceeds;
    var totalCf = rows.reduce(function (s, r) { return s + r.cashFlow; }, 0);
    var first = rows[0];
    return {
      down: down, loan: loan, cashIn: cashIn, payment: pmt, value0: value0, rows: rows,
      noi1: first.noi, opex1: first.opex, cashFlow1: first.cashFlow,
      capRate: value0 > 0 ? first.noi / value0 : NaN,
      coc: cashIn > 0 ? first.cashFlow / cashIn : NaN,
      dscr: first.debt > 0 ? first.noi / first.debt : NaN,
      salePrice: salePrice, proceeds: proceeds, profit: totalCf + proceeds - cashIn,
      irr: irr(flows)
    };
  }
  // --- calc end

  function num(id) {
    var raw = document.getElementById(id).value;
    if (id === 'rpArv' && raw.trim() === '') return 0;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) {
    return isFinite(x) ? (x * 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%' : '–';
  }

  var OUT = ['rpCashFlow', 'rpCoc', 'rpCap', 'rpIrr', 'rpCashIn', 'rpLoan', 'rpPayment', 'rpNoi', 'rpOpex', 'rpDscr',
             'rpSalePrice', 'rpProceeds', 'rpProfit'];

  function update() {
    var p = {
      price: num('rpPrice'), closing: num('rpClosing'), downPct: num('rpDown'), rate: num('rpRate'), term: Math.round(num('rpTerm')),
      rent: num('rpRent'), otherIncome: num('rpOtherIncome'), vacancy: num('rpVacancy'), management: num('rpManagement'),
      tax: num('rpTax'), insurance: num('rpInsurance'), maintenance: num('rpMaintenance'), hoa: num('rpHoa'), otherCost: num('rpOtherCost'),
      rentGrowth: num('rpRentGrowth'), costGrowth: num('rpCostGrowth'), appreciation: num('rpAppreciation'),
      hold: Math.round(num('rpHold')), sellCost: num('rpSellCost'), repairs: num('rpRepairs'), arv: num('rpArv')
    };
    var dollars = ['price', 'closing', 'rent', 'otherIncome', 'tax', 'insurance', 'maintenance', 'hoa', 'otherCost', 'repairs', 'arv'];
    var msg = '';
    if (dollars.some(function (k) { return isNaN(p[k]) || p[k] < 0 || p[k] > 1e10; })) msg = 'Enter dollar amounts of $0 or more.';
    else if (p.price <= 0) msg = 'Enter a purchase price above $0.';
    else if (isNaN(p.downPct) || p.downPct < 0 || p.downPct > 100) msg = 'Enter a down payment from 0% to 100%.';
    else if (isNaN(p.rate) || p.rate < 0 || p.rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(p.term) || p.term < 1 || p.term > 40) msg = 'Enter a loan term of 1 to 40 years.';
    else if ([p.vacancy, p.management].some(function (v) { return isNaN(v) || v < 0 || v > 100; })) msg = 'Enter vacancy and management rates from 0% to 100%.';
    else if ([p.rentGrowth, p.costGrowth, p.appreciation].some(function (v) { return isNaN(v) || v < -20 || v > 20; })) msg = 'Enter yearly increases between -20% and 20%.';
    else if (isNaN(p.hold) || p.hold < 1 || p.hold > 40) msg = 'Enter a holding period of 1 to 40 years.';
    else if (isNaN(p.sellCost) || p.sellCost < 0 || p.sellCost > 50) msg = 'Enter selling costs from 0% to 50%.';
    var error = document.getElementById('rpError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) {
      OUT.forEach(function (id) { document.getElementById(id).textContent = '–'; });
      document.getElementById('rpSchedule').innerHTML = '';
      return;
    }
    ['downPct', 'rate', 'vacancy', 'management', 'rentGrowth', 'costGrowth', 'appreciation', 'sellCost'].forEach(function (k) { p[k] /= 100; });
    var r = analyze(p);
    document.getElementById('rpCashFlow').textContent = money2.format(r.cashFlow1 / 12);
    document.getElementById('rpCoc').textContent = r.cashIn > 0 ? pct(r.coc) : '–';
    document.getElementById('rpCap').textContent = pct(r.capRate);
    document.getElementById('rpIrr').textContent = r.cashIn > 0 && isFinite(r.irr) ? pct(r.irr) : 'Not defined';
    document.getElementById('rpCashIn').textContent = money.format(r.cashIn);
    document.getElementById('rpLoan').textContent = money.format(r.loan);
    document.getElementById('rpPayment').textContent = money2.format(r.payment) + '/mo';
    document.getElementById('rpNoi').textContent = money.format(r.noi1);
    document.getElementById('rpOpex').textContent = money.format(r.opex1);
    document.getElementById('rpDscr').textContent = isFinite(r.dscr) ? r.dscr.toFixed(2) + '×' : 'No loan';
    document.getElementById('rpSaleLabel').textContent = 'Sale price after ' + p.hold + (p.hold === 1 ? ' year' : ' years');
    document.getElementById('rpSalePrice').textContent = money.format(r.salePrice);
    document.getElementById('rpProceeds').textContent = money.format(r.proceeds);
    document.getElementById('rpProfit').textContent = money.format(r.profit);
    document.getElementById('rpSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.collected) + '</td><td>' + money.format(row.opex) + '</td><td>' +
             money.format(row.noi) + '</td><td>' + money.format(row.debt) + '</td><td>' + money.format(row.cashFlow) + '</td><td>' +
             money.format(row.value - row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
